def longest_common_prefix(words):
    if not words:
        return ""
    root = {}
    END = "$end"
    for word in words:
        node = root
        node["$cnt"] = node.get("$cnt", 0) + 1
        for ch in word:
            node = node.setdefault(ch, {})
            node["$cnt"] = node.get("$cnt", 0) + 1
        node[END] = True

    n = len(words)
    prefix_chars = []
    node = root
    for ch in words[0]:
        child = node.get(ch)
        if child is None or child.get("$cnt", 0) != n:
            break
        prefix_chars.append(ch)
        node = child
    return "".join(prefix_chars)
